    g.moveTo(11, 12);
    g.lineTo(182, 12);
    g.lineTo(182, 188);
    g.lineTo(96.5, 158);
    g.lineTo(11, 188);
    g.closePath();
    g.fillStyle = grad;
    g.fill();

    /* Orillo de la driza, por dentro del borde de la tela. */
    g.fillStyle = '#E4C07A';
    g.fillRect(0, 6, 13, 188);
    g.globalAlpha = 0.5;
    g.fillStyle = '#8A6A33';
