      { x: 62, y: 46, z: -92, scale: 132, hex: '#69D3C1', opacity: 0.085, phase: 2.1, speed: 0.17 },
      { x: 20, y: 32, z: 108, scale: 140, hex: '#C49BFF', opacity: 0.075, phase: 4.2, speed: 0.13 }
